def first_index(values, target):
    for index in range(len(values)):
        if values[index] == target:
            return index
    return -1

print(first_index([4, 2, 4], 4))
print(first_index([4, 2, 4], 9))
print(first_index([], 4))

def first_index(values, target):
    for index in range(len(values)):
        if values[index] == target:
            return index
    return -1

print(first_index([4, 2, 4], 4))
print(first_index([4, 2, 4], 9))
print(first_index([], 4))

def all_indices(values, target):
    result = []
    for index, value in enumerate(values):
        if value == target:
            result.append(index)
    return result

print(all_indices([2, 5, 2, 2], 2))
print(all_indices([1, 3], 2))
print(all_indices([], 2))

def first_at_least(values, limit):
    for index, value in enumerate(values):
        if value >= limit:
            return index
    return -1

print(first_at_least([9, 1, 7], 7))
print(first_at_least([1, 4, 3], 4))
print(first_at_least([], 0))

def find_from(values, target, start):
    if start < 0 or start > len(values):
        raise ValueError("start out of range")
    for index in range(start, len(values)):
        if values[index] == target:
            return index
    return -1

print(find_from([3, 1, 3], 3, 1))
print(find_from([3], 3, 1))
print(find_from([], 3, 0))
try:
    find_from([3], 3, -1)
except ValueError:
    print("ValueError")
